record.field:
{
         "editForm": {
         "file": [
            {
                "key": "file",
                "components": [
                    {
                        "key": "storage",
                        "defaultValue": "url",
                        "description": "This js option use for storing the file on minio of openg2p-portal"
                    },
                    {"key": "url", "defaultValue": "/v1/selfservice/uploadDocument"}
                ]
            },
            {
                "key": "data",
                "components": [
                    {"key": "persistent", "ignore": true},
                    {"key": "protected", "ignore": true},
                    {"key": "dbIndex", "ignore": true},
                    {"key": "encrypted", "ignore": true},
                    {"key": "calculateServer", "ignore": true}
                ]
            },
            {
                "key": "layout",
                "components": [
                    {"key": "overlay", "ignore": true}
                ]
            }
          ]
         }
           }
